{"implementation": "def solve(case):
    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])

    # Validate required fields
    for n in nodes:
        for field in ["id", "parent", "symbol", "depth", "removable", "utility"]:
            if field not in n:
                raise ValueError(f"Missing field '{field}' in node {n.get('id', '?')}")

    # Build lookup structures
    node_map = {n["id"]: n for n in nodes}
    children = {n["id"]: [] for n in nodes}
    for n in nodes:
        if n["parent"] is not None:
            if n["parent"] not in node_map:
                raise ValueError(f"Node {n['id']} references unknown parent {n['parent']}")
            children[n["parent"]].append(n["id"])

    # Sort: deepest first, then lexicographic node ID as stable tie-break
    sorted_nodes = sorted(nodes, key=lambda n: (-n["depth"], n["id"]))

    retained = set(n["id"] for n in nodes)
    removed_order = []

    for n in sorted_nodes:
        nid = n["id"]

        # Never remove non-removable nodes
        if not n["removable"]:
            continue

        # Never remove the root (parent is None)
        if n["parent"] is None:
            continue

        # Never remove a node that has retained children
        if any(child in retained for child in children[nid]):
            continue

        # Tentatively remove: check all required symbols remain represented
        retained.remove(nid)
        symbols_present = set(node_map[rid]["symbol"] for rid in retained)
        if required_symbols.issubset(symbols_present):
            # Removal is valid; record it
            removed_order.append(nid)
        else:
            # Restore: required symbol coverage would be broken
            retained.add(nid)

    retained_sorted = sorted(retained)

    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": retained_sorted
    }
